import {readFileSync} from 'node:fs';
import {createSimulation} from '../../src/game/core/simulation.ts';
import {migrateToV4} from '../../src/game/persistence/save-v4.ts';
export const giraffeSource=JSON.parse(readFileSync(new URL('./giraffe-v3-golden.json',import.meta.url),'utf8')).state;
export function preparedGiraffeZoo(companions=true){const sim=createSimulation(migrateToV4(giraffeSource).value),must=r=>{if(!r.ok)throw Error(JSON.stringify(r));return r;},q={command:sim.commandRevision()},grant=must(sim.prepareGiraffeGrant(q));if(!sim.acceptCommittedGiraffeGrant(grant.state,q))throw Error('Synthetic grant adoption failed');must(sim.buildGiraffeHabitat(sim.giraffeHabitatView().anchor,'habitat-giraffe-render',sim.commandRevision()));for(const kind of ['giraffe-browse','giraffe-browse','giraffe-water','giraffe-shade'])must(sim.placeGiraffeCare({kind,cell:sim.defaultGiraffeCareCell(kind),command:sim.commandRevision()}));for(const r of sim.giraffeCareView().resources)if(r.refillPrice)must(sim.refillGiraffeCare({id:r.id,revision:r.revision,command:sim.commandRevision()}));must(sim.welcomeGiraffes(sim.commandRevision()));if(companions)must(sim.welcomeGiraffes(sim.commandRevision()));return sim;}
